using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SyphonHourglassCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/SyphonHourglassCustomDescription", order = 0)]
public class SyphonHourglassCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		SyphonHourglassAction syphonHourglassAction = battleAction as SyphonHourglassAction;
		string arg = syphonHourglassAction.GainSandsOfTimeEffectAction.GetActionDescription(syphonHourglassAction.OneEffectSandsOfTimeAmount).RemoveLast();
		string text = syphonHourglassAction.GainSandsOfTimeEffectAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).LowercaseFirst();
		if (LanguagesIndexes.IsCurrentLanguageSimplifiedChinese() || LanguagesIndexes.IsCurrentLanguageKorean() || LanguagesIndexes.IsCurrentLanguageTraditionalChinese() || LanguagesIndexes.IsCurrentLanguageJapanese())
		{
			return Smart.Format(rawLocalizedDescription, arg, text);
		}
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), arg, Smart.Format(rawLocalizedDescription, text));
	}
}
